package com.hmdp.ai.api.artifact;import com.hmdp.ai.api.security.RequireAiPermission;import com.hmdp.ai.application.artifact.ArtifactApplicationService;import com.hmdp.ai.domain.artifact.ArtifactContent;import com.hmdp.ai.domain.security.AiPermission;import org.springframework.core.io.InputStreamResource;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.nio.charset.StandardCharsets;
@RestController @RequestMapping("/api/v1/artifacts") @RequireAiPermission(AiPermission.AGENT_RUN) public class ArtifactController {private final ArtifactApplicationService service;public ArtifactController(ArtifactApplicationService service){this.service=service;}@GetMapping("/{id}")public ResponseEntity<InputStreamResource>download(@PathVariable String id){ArtifactContent value=service.download(id);String safe=value.getRecord().getName().replaceAll("[\\r\\n\"]","_");ContentDisposition disposition=ContentDisposition.attachment().filename(safe,StandardCharsets.UTF_8).build();return ResponseEntity.ok().contentType(MediaType.parseMediaType(value.getRecord().getContentType())).contentLength(value.getRecord().getSizeBytes()).header(HttpHeaders.CONTENT_DISPOSITION,disposition.toString()).body(new InputStreamResource(value.getContent()));}}
